+                                            RequestSnapshotState::Queued
+                                                | RequestSnapshotState::Running
+                                                | RequestSnapshotState::WaitingForPermission
+                                                | RequestSnapshotState::Cancelling
+                                        )
+                                })
+                            })
+                        });
