+                    }
+                    Ok(_) => log::warn!("attention requests fetch not ok"),
+                    Err(err) => log::warn!("attention requests decode error: {err}"),
+                },
+                Err(err) => log::warn!("attention requests fetch error: {err}"),
+            }
