     1	//! Shared fuzzy matching for keyboard-first Ocean search surfaces.
     2	
     3	/// Score a case-insensitive subsequence match.
     4	///
     5	/// Matches at the start of the target, word boundaries, consecutive runs, and
     6	/// prefixes receive bonuses. `None` means the query is not a subsequence.
     7	pub(crate) fn fuzzy_score(query: &str, target: &str) -> Option<f64> {
     8	    if query.is_empty() {
     9	        return Some(0.0);
    10	    }
    11	
    12	    let query_lower = query.to_lowercase();
    13	    let target_lower = target.to_lowercase();
    14	    let query_chars: Vec<char> = query_lower.chars().collect();
    15	    let target_chars: Vec<char> = target_lower.chars().collect();
    16	    // Boundary detection needs the original case so camelCase transitions
    17	    // survive normalization.
    18	    let target_orig: Vec<char> = target.chars().collect();
    19	
    20	    let mut score = 0.0;
    21	    let mut qi = 0usize;
    22	    let mut prev_match = None;
    23	    let mut consecutive = 0usize;
    24	
    25	    for (ti, tc) in target_chars.iter().enumerate() {
    26	        if qi >= query_chars.len() {
    27	            break;
    28	        }
    29	        if *tc != query_chars[qi] {
    30	            continue;
    31	        }
    32	
    33	        let mut char_score = 1.0;
    34	        if ti == 0 {
    35	            char_score += 10.0;
    36	        }
    37	        if ti < target_orig.len() && is_word_boundary(&target_orig, ti) {
    38	            char_score += 5.0;
    39	        }
    40	        if let Some(prev) = prev_match {
    41	            if ti == prev + 1 {
    42	                consecutive += 1;
    43	                char_score += 2.0 * consecutive as f64;
    44	            } else {
    45	                consecutive = 0;
    46	            }
    47	        }
    48	        if qi == ti {
    49	            char_score += 3.0;
    50	        }
    51	
    52	        score += char_score;
    53	        prev_match = Some(ti);
    54	        qi += 1;
    55	    }
    56	
    57	    (qi == query_chars.len()).then_some(score)
    58	}
    59	
    60	/// Whether `chars[idx]` begins a word: index zero, after a separator, or at a
    61	/// lower-to-upper camelCase transition.
    62	pub(crate) fn is_word_boundary(chars: &[char], idx: usize) -> bool {
    63	    if idx == 0 {
    64	        return true;
    65	    }
    66	    let prev = chars[idx - 1];
    67	    let curr = chars[idx];
    68	    matches!(prev, ' ' | '-' | '_' | '/' | '.') || (prev.is_lowercase() && curr.is_uppercase())
    69	}
    70	
    71	#[cfg(test)]
    72	mod tests {
    73	    use super::*;
    74	
    75	    #[test]
    76	    fn empty_query_scores_zero() {
    77	        assert_eq!(fuzzy_score("", "anything"), Some(0.0));
    78	    }
    79	
    80	    #[test]
    81	    fn exact_match_scores_positive() {
    82	        assert!(fuzzy_score("files", "files").expect("match") > 0.0);
    83	    }
    84	
    85	    #[test]
    86	    fn exact_prefix_scores_higher_than_word_boundary() {
    87	        let prefix = fuzzy_score("fp", "FilesPanel").expect("match");
    88	        let boundary = fuzzy_score("fp", "SomeFilePanel").expect("match");
    89	        assert!(prefix > boundary);
    90	    }
    91	
    92	    #[test]
    93	    fn word_boundary_scores_higher_than_scattered() {
    94	        let boundary = fuzzy_score("fp", "SomeFilePanel").expect("match");
    95	        let scattered = fuzzy_score("mp", "somefilepanel").expect("match");
    96	        assert!(boundary > scattered);
    97	    }
    98	
    99	    #[test]
   100	    fn scattered_subsequence_still_matches() {
   101	        assert!(fuzzy_score("smp", "somefilepanel").is_some());
   102	    }
   103	
   104	    #[test]
   105	    fn missing_char_returns_none() {
   106	        assert_eq!(fuzzy_score("xyz", "abcdef"), None);
   107	    }
   108	
   109	    #[test]
   110	    fn matching_is_case_insensitive() {
   111	        assert_eq!(fuzzy_score("files", "FILES"), fuzzy_score("FILES", "files"));
   112	    }
   113	
   114	    #[test]
   115	    fn consecutive_bonus_compounds() {
   116	        let consecutive = fuzzy_score("fil", "files").expect("match");
   117	        let scattered = fuzzy_score("fls", "files").expect("match");
   118	        assert!(consecutive > scattered);
   119	    }
   120	
   121	    #[test]
   122	    fn word_boundaries_cover_separators_and_camelcase() {
   123	        assert!(is_word_boundary(&['a', 'b'], 0));
   124	        assert!(is_word_boundary(&['a', ' ', 'b'], 2));
   125	        assert!(is_word_boundary(&['a', '-', 'b'], 2));
   126	        assert!(is_word_boundary(&['a', '_', 'b'], 2));
   127	        assert!(is_word_boundary(&['a', '/', 'b'], 2));
   128	        assert!(is_word_boundary(&['a', '.', 'b'], 2));
   129	        assert!(is_word_boundary(&['a', 'B'], 1));
   130	        assert!(!is_word_boundary(&['a', 'b', 'c'], 1));
   131	        assert!(!is_word_boundary(&['A', 'B', 'C'], 1));
   132	    }
   133	}

