 37	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
 38	pub enum IslandAttentionState {
 39	    NeedsHuman,
 40	    Failed,
 41	    Cancelling,
 42	    Running,
 43	}
 44	
 45	impl IslandAttentionState {
 46	    pub(crate) fn rank(self) -> u8 {
 47	        match self {
 48	            Self::NeedsHuman => 0,
 49	            Self::Failed => 1,
 50	            Self::Cancelling => 2,
 51	            Self::Running => 3,
 52	        }
 53	    }
 54	
 55	    pub(crate) fn label(self) -> &'static str {
 56	        match self {
 57	            Self::NeedsHuman => "Needs attention",
 58	            Self::Failed => "Failed",
 59	            Self::Cancelling => "Stopping",
 60	            Self::Running => "Running",
 61	        }
 62	    }
 63	
 64	    pub(crate) fn class_name(self) -> &'static str {
 65	        match self {
 66	            Self::NeedsHuman => "is-needs-human",
 67	            Self::Failed => "is-failed",
 68	            Self::Cancelling => "is-cancelling",
 69	            Self::Running => "is-running",
 70	        }
 71	    }
 72	}
 73	
 74	#[derive(Clone, Debug, PartialEq, Eq)]
 75	pub struct IslandAttentionItem {
 76	    pub id: String,
 77	    pub request_id: String,
 78	    pub permission_id: Option<String>,
 79	    pub session_id: Option<String>,
 80	    pub session_title: String,
 81	    pub project: Option<String>,
 82	    pub tool: Option<String>,
 83	    pub detail: String,
 84	    pub updated_at: String,
 85	    pub state: IslandAttentionState,
 86	}
 87	
 88	fn session_attention_metadata(
 89	    sessions: &[IslandSession],
 90	    session_id: Option<&str>,
 91	) -> (String, Option<String>) {
 92	    if let Some(session) =
 93	        session_id.and_then(|id| sessions.iter().find(|session| session.id == id))
 94	    {
 95	        return (session.title.clone(), session.project.clone());
 96	    }
 97	    match session_id {
 98	        Some(id) => (
 99	            format!("Session {}", id.chars().take(8).collect::<String>()),
100	            None,
101	        ),
102	        None => ("Daemon request".to_string(), None),
103	    }
104	}
105	
106	fn bounded_detail(value: &str) -> String {
107	    const LIMIT: usize = 240;
108	    let trimmed = value.trim();
109	    let mut chars = trimmed.chars();
110	    let prefix = chars.by_ref().take(LIMIT).collect::<String>();
111	    if chars.next().is_some() {
112	        format!("{prefix}…")
113	    } else {
114	        prefix
115	    }
116	}
117	
118	fn request_updated_at(request: &RequestSnapshot) -> String {
119	    request
120	        .updated_at
121	        .as_deref()
122	        .or(request.finished_at.as_deref())
123	        .or(request.started_at.as_deref())
124	        .unwrap_or_default()
125	        .to_string()
126	}
127	
128	/// Fold the daemon's global status-only request snapshot into a compact,
129	/// truthful activity projection. A focused waiting request may be enriched from
130	/// the existing focused permission SSE state; background permission detail is
131	/// never polled. Terminal success/cancellation is omitted, and stale failure
132	/// noise is bounded to the newest three authoritative errored requests.
133	pub(crate) fn derive_attention_items(
134	    requests: &[RequestSnapshot],
135	    sessions: &[IslandSession],
136	    focused_session_id: Option<&str>,
137	    active_request_id: Option<&str>,
138	    focused_permissions: &[PendingPermission],
139	) -> Vec<IslandAttentionItem> {
140	    let mut ordered_requests = requests.iter().collect::<Vec<_>>();
141	    ordered_requests.sort_by(|a, b| {
142	        request_updated_at(b)
143	            .cmp(&request_updated_at(a))
144	            .then_with(|| a.request_id.cmp(&b.request_id))
145	    });
146	
147	    let mut items = Vec::new();
148	    let mut failed_count = 0usize;
149	    for request in ordered_requests {
150	        let state = match request.state {
151	            RequestSnapshotState::Queued | RequestSnapshotState::Running => {
152	                IslandAttentionState::Running
153	            }
154	            RequestSnapshotState::WaitingForPermission => IslandAttentionState::NeedsHuman,
155	            RequestSnapshotState::Cancelling => IslandAttentionState::Cancelling,
156	            RequestSnapshotState::Errored if failed_count < 3 => {
157	                failed_count += 1;
158	                IslandAttentionState::Failed
159	            }
160	            RequestSnapshotState::Errored
161	            | RequestSnapshotState::Cancelled
162	            | RequestSnapshotState::Completed => continue,
163	        };
164	        let (session_title, project) =
165	            session_attention_metadata(sessions, request.session_id.as_deref());
166	        let focused_permission = (state == IslandAttentionState::NeedsHuman
167	            && active_request_id == Some(request.request_id.as_str())
168	            && request.session_id.as_deref() == focused_session_id)
169	            .then(|| {
170	                let permission_id = request.permission_id.as_deref()?;
171	                focused_permissions.iter().find(|permission| {
172	                    permission.permission_id == permission_id
173	                        && Some(permission.session_id.as_str()) == focused_session_id
174	                })
175	            })
176	            .flatten();
177	        let tool = focused_permission
178	            .map(|permission| permission.tool.trim())
179	            .filter(|tool| !tool.is_empty())
180	            .map(str::to_string);
181	        let detail = focused_permission
182	            .map(|permission| permission.reason.trim())
183	            .filter(|reason| !reason.is_empty())
184	            .map(bounded_detail)
185	            .or_else(|| {
186	                request
187	                    .message
188	                    .as_deref()
189	                    .map(str::trim)
190	                    .filter(|message| !message.is_empty())
191	                    .map(bounded_detail)
192	            })
193	            .or_else(|| {
194	                tool.as_deref()
195	                    .map(|tool| format!("Review requested access for {tool}"))
196	            })
197	            .unwrap_or_else(|| state.label().to_string());
198	        items.push(IslandAttentionItem {
199	            id: format!("request:{}", request.request_id),
200	            request_id: request.request_id.clone(),
201	            permission_id: request.permission_id.clone(),
202	            session_id: request.session_id.clone(),
203	            session_title,
204	            project,
205	            tool,
206	            detail,
207	            updated_at: request_updated_at(request),
208	            state,
209	        });
210	    }
211	
212	    items.sort_by(|a, b| {
213	        a.state
214	            .rank()
215	            .cmp(&b.state.rank())
216	            .then_with(|| b.updated_at.cmp(&a.updated_at))
217	            .then_with(|| a.id.cmp(&b.id))
218	    });
219	    items
220	}
