247	
248	pub(crate) fn permission_action_state(
249	    permission_id: Option<&str>,
250	    request_id: &str,
251	    session_id: Option<&str>,
252	    focused_id: Option<&str>,
253	    active_request_id: Option<&str>,
254	    has_decision_token: bool,
255	    pending: &[PendingPermission],
256	) -> Option<bool> {
257	    let permission_id = permission_id?;
258	    let session_id = session_id?;
259	    if !has_decision_token
260	        || focused_id != Some(session_id)
261	        || active_request_id != Some(request_id)
262	    {
263	        return None;
264	    }
265	    pending
266	        .iter()
267	        .find(|item| item.permission_id == permission_id && item.session_id == session_id)
268	        .map(|item| item.deciding)
269	}
270	
271	pub(crate) fn stop_action_state(
272	    state: IslandAttentionState,
273	    request_id: &str,
274	    cancellations: &[String],
275	) -> Option<bool> {
276	    (state == IslandAttentionState::Running)
277	        .then(|| cancellations.iter().any(|pending| pending == request_id))
278	}
279	
280	pub(crate) fn compact_attention_counts(items: &[IslandAttentionItem]) -> (usize, usize) {
281	    let needs_human = items
282	        .iter()
283	        .filter(|item| item.state == IslandAttentionState::NeedsHuman)
284	        .count();
285	    let running = items
286	        .iter()
287	        .filter(|item| item.state == IslandAttentionState::Running)
288	        .count();
289	    (needs_human, running)
290	}
291	
292	fn recently_updated(updated_at: &str) -> bool {
293	    #[cfg(target_arch = "wasm32")]
294	    {
295	        is_recent(updated_at)
296	    }
297	    #[cfg(not(target_arch = "wasm32"))]
298	    {
299	        // Browser time is intentionally unavailable in native unit tests.
300	        // Sorting remains fully deterministic there; production uses the
301	        // shared sessions-panel recency window above.
302	        let _ = updated_at;
303	        false
304	    }
305	}
306	
307	/// Project daemon sessions into the compact metadata used by the Island.
308	pub(crate) fn derive_island_sessions(
309	    sessions: &[SessionSummary],
310	    projects: &[ProjectInfo],
311	    focused_id: Option<&str>,
312	) -> Vec<IslandSession> {
313	    let mut items: Vec<_> = sessions
314	        .iter()
315	        .map(|session| {
316	            let root = session_root(session).to_string();
317	            let project = session
318	                .owning_project
319	                .as_ref()
320	                .map(|owner| {
321	                    if owner.name.trim().is_empty() {
322	                        owner.id.clone()
323	                    } else {
324	                        owner.name.trim().to_string()
325	                    }
326	                })
327	                .or_else(|| {
328	                    project_for_root(projects, &root).map(|project| {
329	                        if project.name.trim().is_empty() {
330	                            project.id.clone()
331	                        } else {
332	                            project.name.trim().to_string()
333	                        }
334	                    })
335	                });
336	            let (origin, clean_title) = split_origin(&session.title);
337	            let title = if clean_title.trim().is_empty() {
338	                "(untitled)".to_string()
339	            } else {
340	                clean_title
341	            };
342	            let is_focused = focused_id == Some(session.id.as_str());
343	            let priority = if is_focused {
344	                IslandPriority::Focused
345	            } else if recently_updated(&session.updated_at) {
346	                IslandPriority::Recent
347	            } else {
348	                IslandPriority::Background
349	            };
350	
351	            IslandSession {
352	                id: session.id.clone(),
353	                title,
354	                project,
355	                cwd: root,
356	                branch: session.git_branch.clone().filter(|value| !value.is_empty()),
357	                origin,
358	                updated_at: session.updated_at.clone(),
359	                turn_count: session.turn_count,
360	                is_focused,
361	                priority,
362	            }
363	        })
364	        .collect();
365	
366	    items.sort_by(|a, b| {
367	        b.is_focused
368	            .cmp(&a.is_focused)
369	            .then_with(|| b.updated_at.cmp(&a.updated_at))
370	            .then_with(|| a.title.to_lowercase().cmp(&b.title.to_lowercase()))
371	            .then_with(|| a.id.cmp(&b.id))
372	    });
373	    items
374	}
375	
376	/// Normalized session document shared by Browse filtering and `Cmd/Ctrl+P`.
377	pub(crate) fn island_search_text(item: &IslandSession) -> String {
378	    let state = match item.priority {
379	        IslandPriority::Focused => "focused",
380	        IslandPriority::Recent => "recent",
381	        IslandPriority::Background => "background",
382	    };
383	    let project = item.project.as_deref().unwrap_or_default();
384	    let branch = item.branch.as_deref().unwrap_or_default();
385	    let origin = item.origin.as_deref().unwrap_or_default();
386	    format!(
387	        "{} {} project:{} {} {} {} {} {} turns",
388	        item.title, project, project, item.cwd, branch, origin, state, item.turn_count
389	    )
390	    .to_lowercase()
391	}
392	
393	/// Search the Island corpus while preserving derivation order for an empty
394	/// query and using focus/recency only as small tie-breaks for real queries.
395	pub(crate) fn search_island(query: &str, items: &[IslandSession]) -> Vec<IslandResult> {
396	    let query = query.trim();
397	    if query.is_empty() {
398	        return items.iter().cloned().map(IslandResult::Session).collect();
399	    }
400	
401	    let query_lower = query.to_lowercase();
402	    let mut scored: Vec<(u8, f64, usize, IslandSession)> = items
403	        .iter()
404	        .enumerate()
405	        .filter_map(|(index, item)| {
406	            let document_score = fuzzy_score(query, &island_search_text(item))?;
407	            let title = item.title.to_lowercase();
408	            let title_score = fuzzy_score(query, &item.title);
409	            let project = item.project.as_deref().map(str::to_lowercase);
410	            let project_score = project
411	                .as_deref()
412	                .and_then(|project| fuzzy_score(query, project));
413	
414	            // Match category is a strict tier; fuzzy score only orders items
415	            // inside a tier, so a long fuzzy title can never outrank an exact
416	            // project (and metadata can never outrank a title/project match).
417	            let (tier, mut score) = if title == query_lower {
418	                (6, title_score.unwrap_or(document_score))
419	            } else if title.starts_with(&query_lower) {
420	                (5, title_score.unwrap_or(document_score))
421	            } else if project.as_deref() == Some(query_lower.as_str()) {
422	                (4, project_score.unwrap_or(document_score))
423	            } else if project
424	                .as_deref()
425	                .is_some_and(|project| project.starts_with(&query_lower))
426	            {
427	                (3, project_score.unwrap_or(document_score))
428	            } else if let Some(title_score) = title_score {
429	                (2, title_score)
430	            } else if let Some(project_score) = project_score {
431	                (1, project_score)
432	            } else {
433	                (0, document_score)
434	            };
435	            score += match item.priority {
436	                IslandPriority::Focused => 2.0,
437	                IslandPriority::Recent => 1.0,
438	                IslandPriority::Background => 0.0,
439	            };
440	            Some((tier, score, index, item.clone()))
441	        })
442	        .collect();
443	
444	    scored.sort_by(|a, b| {
445	        b.0.cmp(&a.0)
446	            .then_with(|| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal))
447	            .then_with(|| a.2.cmp(&b.2))
448	            .then_with(|| a.3.id.cmp(&b.3.id))
449	    });
450	    scored
451	        .into_iter()
452	        .map(|(_, _, _, item)| IslandResult::Session(item))
453	        .collect()
454	}
