248	pub(crate) fn permission_action_state(
249	    permission_id: Option<&str>,
250	    request_id: &str,
251	    session_id: Option<&str>,
252	    focused_id: Option<&str>,
253	    active_request_id: Option<&str>,
254	    has_decision_token: bool,
255	    pending: &[PendingPermission],
256	) -> Option<bool> {
257	    let permission_id = permission_id?;
258	    let session_id = session_id?;
259	    if !has_decision_token
260	        || focused_id != Some(session_id)
261	        || active_request_id != Some(request_id)
262	    {
263	        return None;
264	    }
265	    pending
266	        .iter()
267	        .find(|item| item.permission_id == permission_id && item.session_id == session_id)
268	        .map(|item| item.deciding)
269	}
