307	/// Project daemon sessions into the compact metadata used by the Island.
308	pub(crate) fn derive_island_sessions(
309	    sessions: &[SessionSummary],
310	    projects: &[ProjectInfo],
311	    focused_id: Option<&str>,
312	) -> Vec<IslandSession> {
313	    let mut items: Vec<_> = sessions
314	        .iter()
315	        .map(|session| {
316	            let root = session_root(session).to_string();
317	            let project = session
318	                .owning_project
319	                .as_ref()
320	                .map(|owner| {
321	                    if owner.name.trim().is_empty() {
322	                        owner.id.clone()
323	                    } else {
324	                        owner.name.trim().to_string()
325	                    }
326	                })
327	                .or_else(|| {
328	                    project_for_root(projects, &root).map(|project| {
329	                        if project.name.trim().is_empty() {
330	                            project.id.clone()
331	                        } else {
332	                            project.name.trim().to_string()
333	                        }
334	                    })
335	                });
336	            let (origin, clean_title) = split_origin(&session.title);
337	            let title = if clean_title.trim().is_empty() {
338	                "(untitled)".to_string()
339	            } else {
340	                clean_title
341	            };
342	            let is_focused = focused_id == Some(session.id.as_str());
343	            let priority = if is_focused {
344	                IslandPriority::Focused
345	            } else if recently_updated(&session.updated_at) {
346	                IslandPriority::Recent
347	            } else {
348	                IslandPriority::Background
349	            };
350	
351	            IslandSession {
352	                id: session.id.clone(),
353	                title,
354	                project,
355	                cwd: root,
356	                branch: session.git_branch.clone().filter(|value| !value.is_empty()),
357	                origin,
358	                updated_at: session.updated_at.clone(),
359	                turn_count: session.turn_count,
360	                is_focused,
361	                priority,
362	            }
363	        })
364	        .collect();
365	
366	    items.sort_by(|a, b| {
367	        b.is_focused
368	            .cmp(&a.is_focused)
369	            .then_with(|| b.updated_at.cmp(&a.updated_at))
370	            .then_with(|| a.title.to_lowercase().cmp(&b.title.to_lowercase()))
371	            .then_with(|| a.id.cmp(&b.id))
372	    });
373	    items
374	}
