376	/// Normalized session document shared by Browse filtering and `Cmd/Ctrl+P`.
377	pub(crate) fn island_search_text(item: &IslandSession) -> String {
378	    let state = match item.priority {
379	        IslandPriority::Focused => "focused",
380	        IslandPriority::Recent => "recent",
381	        IslandPriority::Background => "background",
382	    };
383	    let project = item.project.as_deref().unwrap_or_default();
384	    let branch = item.branch.as_deref().unwrap_or_default();
385	    let origin = item.origin.as_deref().unwrap_or_default();
386	    format!(
387	        "{} {} project:{} {} {} {} {} {} turns",
388	        item.title, project, project, item.cwd, branch, origin, state, item.turn_count
389	    )
390	    .to_lowercase()
391	}
