 63	fn history_result_label(hit: &HistorySearchHit) -> String {
 64	    let title = if hit.session_title.trim().is_empty() {
 65	        "Untitled session"
 66	    } else {
 67	        hit.session_title.trim()
 68	    };
 69	    let role = if hit.role.trim().is_empty() {
 70	        "transcript"
 71	    } else {
 72	        hit.role.trim()
 73	    };
 74	    let excerpt = bounded_accessible_excerpt(&hit.excerpt);
 75	    format!("Open {role} history match from {title}: {excerpt}")
 76	}
 77	
 78	fn recall_should_retire(previous: IslandMode, next: IslandMode) -> bool {
 79	    previous == IslandMode::Recall && next != IslandMode::Recall
 80	}
 81	
 82	fn should_submit_agent_prompt(is_composing: bool, text: &str) -> bool {
 83	    !is_composing && !text.trim().is_empty()
 84	}
 85	
 86	fn scroll_follow_target(
 87	    view_top: i32,
 88	    view_height: i32,
 89	    item_top: i32,
 90	    item_height: i32,
 91	) -> Option<i32> {
 92	    if item_top < view_top {
 93	        Some(item_top)
 94	    } else {
 95	        let item_bottom = item_top.saturating_add(item_height);
 96	        let view_bottom = view_top.saturating_add(view_height);
 97	        (item_bottom > view_bottom).then_some(item_bottom.saturating_sub(view_height))
 98	    }
 99	}
100	
101	fn scroll_selected_row(container: Option<web_sys::HtmlElement>, row_id: &str) {
102	    let Some(container) = container else { return };
103	    let Ok(Some(row)) = container.query_selector(&format!("#{row_id}")) else {
104	        return;
105	    };
106	    let Ok(row) = row.dyn_into::<web_sys::HtmlElement>() else {
107	        return;
108	    };
109	    let container_rect = container.get_bounding_client_rect();
110	    let row_rect = row.get_bounding_client_rect();
111	    let view_top = container.scroll_top();
112	    let item_top = view_top.saturating_add((row_rect.top() - container_rect.top()).round() as i32);
113	    if let Some(target) = scroll_follow_target(
114	        view_top,
115	        container.client_height(),
116	        item_top,
117	        row_rect.height().round() as i32,
118	    ) {
119	        container.set_scroll_top(target);
120	    }
121	}
