178	fn AgentStage(
179	    daemon: Daemon,
180	    items: Memo<Vec<IslandAttentionItem>>,
181	    selected_index: RwSignal<usize>,
182	    on_close: Callback<()>,
183	    on_mode: Callback<IslandMode>,
184	) -> impl IntoView {
185	    let prompt = RwSignal::new(String::new());
186	    let prompt_composing = RwSignal::new(false);
187	    let prompt_ref: NodeRef<leptos::html::Input> = NodeRef::new();
188	    let focused_id = daemon.session_id;
189	    let active_request_id = daemon.active_turn_id;
190	    let pending_permissions = daemon.pending_permissions;
191	    let active_decision_token = daemon.active_decision_token;
192	    let request_cancellations = daemon.request_cancellations;
193	    let status = daemon.status;
194	    let daemon = StoredValue::new(daemon);
195	
196	    Effect::new(move |_| {
197	        let len = items.get().len();
198	        if len == 0 {
199	            selected_index.set(0);
200	            request_animation_frame(move || {
201	                if let Some(input) = prompt_ref.get() {
202	                    let _ = input.focus();
203	                }
204	            });
205	        } else if selected_index.get() >= len {
206	            selected_index.set(0);
207	        }
208	    });
209	
210	    let submit = move |event: SubmitEvent| {
211	        event.prevent_default();
212	        let text = prompt.get_untracked().trim().to_string();
213	        if !should_submit_agent_prompt(prompt_composing.get_untracked(), &text) {
214	            return;
215	        }
216	        daemon.get_value().send_prompt(text);
217	        prompt.set(String::new());
218	        on_close.run(());
219	    };
220	
221	    view! {
222	        <section class="island-agent" aria-label="Agent interaction">
223	            <header class="island-stage__header">
224	                <div class="island-stage__identity">
225	                    <span class="island-stage__eyebrow">"Agent"</span>
226	                    <strong>{move || {
227	                        if items.get().is_empty() { "Focused agent" } else { "Current work" }
228	                    }}</strong>
229	                </div>
230	                <div class="island-stage__routes" aria-label="Island tools">
231	                    <button type="button" on:click=move |_| on_mode.run(IslandMode::Sessions)>
232	                        "Sessions"
233	                    </button>
234	                    <button type="button" on:click=move |_| on_mode.run(IslandMode::Recall)>
235	                        "Recall"
236	                    </button>
237	                </div>
238	            </header>
239	
240	            <Show when=move || items.get().is_empty()>
241	                <div class="island-agent__idle">
242	                    <span class="island-agent__pulse" aria-hidden="true"></span>
243	                    <div>
244	                        <strong>"Ocean is ready"</strong>
245	                        <p>{move || status.get()}</p>
246	                    </div>
247	                </div>
248	                <form class="island-agent__composer" on:submit=submit>
249	                    <input
250	                        node_ref=prompt_ref
251	                        type="text"
252	                        aria-label="Ask Ocean in the focused session"
253	                        placeholder="Ask Ocean…"
254	                        autocomplete="off"
255	                        prop:value=move || prompt.get()
256	                        on:input=move |event| prompt.set(event_target_value(&event))
257	                        on:compositionstart=move |_| prompt_composing.set(true)
258	                        on:compositionend=move |_| prompt_composing.set(false)
259	                        on:keydown=move |event: KeyboardEvent| {
260	                            if event.key() == "Enter"
261	                                && (event.is_composing() || prompt_composing.get_untracked())
262	                            {
263	                                event.prevent_default();
264	                            }
265	                        }
266	                    />
267	                    <button type="submit" disabled=move || prompt.get().trim().is_empty()>
268	                        "Send"
269	                    </button>
270	                </form>
271	            </Show>
272	
273	            <Show when=move || !items.get().is_empty()>
274	                <Show when=move || items.get().len().ge(&2)>
275	                    <div class="island-agent__position">
276	                        <span>{move || {
277	                            let len = items.get().len();
278	                            format!("Work {} of {len}", selected_index.get().min(len.saturating_sub(1)) + 1)
279	                        }}</span>
280	                        <div class="island-agent__stepper">
281	                            <button
282	                                type="button"
283	                                aria-label="Previous agent work item"
284	                                on:click=move |_| {
285	                                    let len = items.get_untracked().len();
286	                                    selected_index.update(|index| *index = previous_index(*index, len));
287	                                }
288	                            >"←"</button>
289	                            <button
290	                                type="button"
291	                                aria-label="Next agent work item"
292	                                on:click=move |_| {
293	                                    let len = items.get_untracked().len();
294	                                    selected_index.update(|index| *index = next_index(*index, len));
295	                                }
296	                            >"→"</button>
297	                        </div>
298	                    </div>
299	                </Show>
300	
301	                <For
302	                    each=move || {
303	                        items
304	                            .get()
305	                            .get(selected_index.get())
306	                            .cloned()
307	                            .into_iter()
308	                            .collect::<Vec<_>>()
309	                    }
310	                    key=agent_view_key
311	                    children=move |item| {
312	                        let item_class = format!(
313	                            "island-agent__work {}",
314	                            item.state.class_name(),
315	                        );
316	                        let state_label = item.state.label();
317	                        let session_name = item.session_title.clone();
318	                        let detail = item.detail.clone();
319	                        let project = item.project.clone().unwrap_or_default();
320	                        let tool = item.tool.clone().unwrap_or_default();
321	                        let updated = if item.updated_at.is_empty() {
322	                            String::new()
323	                        } else {
324	                            fmt_relative_time(&item.updated_at)
325	                        };
326	                        let permission_id = StoredValue::new_local(item.permission_id.clone());
327	                        let permission_session = StoredValue::new_local(item.session_id.clone());
328	                        let open_target = StoredValue::new_local((
329	                            item.session_id.clone(),
330	                            item.session_title.clone(),
331	                        ));
332	                        let request_id = StoredValue::new_local(item.request_id.clone());
333	                        let item_state = item.state;
334	                        let permission_action = Memo::new(move |_| {
335	                            permission_action_state(
336	                                permission_id.get_value().as_deref(),
337	                                &request_id.get_value(),
338	                                permission_session.get_value().as_deref(),
339	                                focused_id.get().as_deref(),
340	                                active_request_id.get().as_deref(),
341	                                active_decision_token.get().is_some(),
342	                                &pending_permissions.get(),
343	                            )
344	                        });
345	                        let stop_action = Memo::new(move |_| {
346	                            stop_action_state(
347	                                item_state,
348	                                &request_id.get_value(),
349	                                &request_cancellations.get(),
350	                            )
351	                        });
352	                        let open_action = Memo::new(move |_| {
353	                            let (session_id, _) = open_target.get_value();
354	                            permission_action.get().is_none()
355	                                && session_id.is_some()
356	                                && session_id.as_deref() != focused_id.get().as_deref()
357	                        });
358	
359	                        view! {
360	                            <article class=item_class>
361	                                <div class="island-agent__work-head">
362	                                    <span class="island-agent__state">
363	                                        <i aria-hidden="true"></i>
364	                                        {state_label}
365	                                    </span>
366	                                    <strong>{session_name}</strong>
367	                                </div>
368	                                <p class="island-agent__detail">{detail}</p>
369	                                <div class="island-agent__meta">
370	                                    <span>{project}</span>
371	                                    <span>{tool}</span>
372	                                    <span>{updated}</span>
373	                                </div>
374	                                <div class="island-agent__actions">
375	                                    <Show when=move || open_action.get()>
376	                                        <button
377	                                            class="island-agent__open"
378	                                            type="button"
379	                                            on:click=move |_| {
380	                                                let (session_id, title) = open_target.get_value();
381	                                                if let Some(session_id) = session_id {
382	                                                    daemon.get_value().switch_session(session_id, title);
383	                                                    on_close.run(());
384	                                                }
385	                                            }
386	                                        >"Open session"</button>
387	                                    </Show>
388	                                    <Show when=move || stop_action.get().is_some()>
389	                                        <button
390	                                            class="island-agent__stop"
391	                                            type="button"
392	                                            disabled=move || stop_action.get().unwrap_or(true)
393	                                            on:click=move |_| {
394	                                                daemon.get_value().cancel_request(request_id.get_value());
395	                                            }
396	                                        >
397	                                            {move || if stop_action.get() == Some(true) { "Stopping…" } else { "Stop" }}
398	                                        </button>
399	                                    </Show>
400	                                    <Show when=move || permission_action.get().is_some()>
401	                                        <button
402	                                            class="island-agent__deny"
403	                                            type="button"
404	                                            disabled=move || permission_action.get().unwrap_or(true)
405	                                            on:click=move |_| {
406	                                                if let Some(permission_id) = permission_id.get_value() {
407	                                                    daemon.get_value().decide_permission(permission_id, false);
408	                                                }
409	                                            }
410	                                        >"Deny"</button>
411	                                        <button
412	                                            class="island-agent__approve"
413	                                            type="button"
414	                                            disabled=move || permission_action.get().unwrap_or(true)
415	                                            on:click=move |_| {
416	                                                if let Some(permission_id) = permission_id.get_value() {
417	                                                    daemon.get_value().decide_permission(permission_id, true);
418	                                                }
419	                                            }
420	                                        >
421	                                            {move || if permission_action.get() == Some(true) { "Working…" } else { "Approve" }}
422	                                        </button>
423	                                    </Show>
424	                                </div>
425	                            </article>
426	                        }
427	                    }
428	                />
429	            </Show>
430	        </section>
431	    }
