101	fn scroll_selected_row(container: Option<web_sys::HtmlElement>, row_id: &str) {
102	    let Some(container) = container else { return };
103	    let Ok(Some(row)) = container.query_selector(&format!("#{row_id}")) else {
104	        return;
105	    };
106	    let Ok(row) = row.dyn_into::<web_sys::HtmlElement>() else {
107	        return;
108	    };
109	    let container_rect = container.get_bounding_client_rect();
110	    let row_rect = row.get_bounding_client_rect();
111	    let view_top = container.scroll_top();
112	    let item_top = view_top.saturating_add((row_rect.top() - container_rect.top()).round() as i32);
113	    if let Some(target) = scroll_follow_target(
114	        view_top,
115	        container.client_height(),
116	        item_top,
117	        row_rect.height().round() as i32,
118	    ) {
119	        container.set_scroll_top(target);
120	    }
121	}
