599	        .parameters
600	        .iter()
601	        .map(|parameter| (parameter.id.clone(), parameter.value))
602	        .collect::<BTreeMap<_, _>>();
603	    let values = RwSignal::new(initial);
604	
605	    let graph_config = config.clone();
606	    let metric_config = config.clone();
607	    let title = config.title.clone();
