619	            {(!title.is_empty()).then(|| view! { <h3 class="interactive-plot__title">{heading}</h3> })}
620	            {(!description.is_empty()).then(|| view! { <p class="interactive-plot__description">{description}</p> })}
621	            <div class="interactive-plot__graph">
622	                {move || match sample_plot(&graph_config, &values.get()) {
623	                    Ok(plot) => {
