629	                            <path class=format!("interactive-plot__line interactive-plot__line--{}", index + 1) d=path></path>
630	                        }).collect::<Vec<_>>();
631	                        let series_labels = graph_config.series.iter()
632	                            .map(|series| series.label.clone())
633	                            .collect::<Vec<_>>();
634	                        let plot_label = format!("Computed plot with series: {}", series_labels.join(", "));
635	                        let legend = series_labels.into_iter().enumerate().map(|(index, label)| view! {
636	                            <span class="interactive-plot__legend-item">
