638	                                    class=format!("interactive-plot__legend-swatch interactive-plot__legend-swatch--{}", index + 1)
639	                                    aria-hidden="true"
640	                                ></i>
641	                                <span>{label}</span>
642	                            </span>
643	                        }).collect::<Vec<_>>();
644	                        view! {
645	                            <div class="interactive-plot__y-label">{graph_config.y_label.clone()}</div>
