660	                        }.into_any()
661	                    }
662	                    Err(error) => view! {
663	                        <div class="interactive-plot__error" role="status">{error}</div>
664	                    }.into_any(),
665	                }}
666	            </div>
667	
668	            {(!metric_config.metrics.is_empty()).then(|| view! {
669	                <div class="interactive-plot__metrics" aria-label="Derived metrics">
670	                    {move || {
671	                        let mut variables = values.get();
