767	    fn eval(source: &str, variables: &[(&str, f64)]) -> Result<f64, String> {
768	        Parser::parse(source)?.evaluate(
769	            &variables
770	                .iter()
771	                .map(|(name, value)| ((*name).into(), *value))
772	                .collect(),
773	        )
774	    }
775	
776	    #[test]
777	    fn expression_engine_supports_precedence_constants_functions_and_variables() {
778	        assert_eq!(eval("2 + 3 * 4", &[]).unwrap(), 14.0);
779	        assert_eq!(eval("2^3^2", &[]).unwrap(), 512.0);
780	        assert!((eval("sin(pi / 2) + max(m, 2)", &[("m", 3.0)]).unwrap() - 4.0).abs() < 1e-10);
781	        assert!(
782	            (eval("exp(ln(e)) + sqrt(9) + abs(-2)", &[]).unwrap() - (std::f64::consts::E + 5.0))
783	                .abs()
784	                < 1e-10
785	        );
786	    }
787	
788	    #[test]
789	    fn expression_engine_rejects_unknown_or_non_finite_work() {
790	        assert!(eval("unknown(1)", &[]).is_err());
791	        assert!(eval("missing + 1", &[]).is_err());
792	        assert!(eval("1 / 0", &[]).is_err());
793	        assert!(Parser::parse(&"1".repeat(MAX_EXPRESSION_LEN + 1)).is_err());
794	    }
795	
796	    fn valid_props() -> Value {
797	        json!({
798	            "title": "Decay",
799	            "parameters": [{"id":"rate", "min":0.1, "max":3.0, "value":1.0}],
800	            "plot": {
801	                "x": {"min":0.0, "max":10.0, "samples":32},
802	                "series": [{"label":"Value", "expression":"exp(-rate*x)"}]
803	            },
804	            "metrics": [{"label":"Half life", "expression":"ln(2)/rate"}]
805	        })
806	    }
807	
808	    #[test]
809	    fn config_clamps_values_and_sample_work() {
810	        let mut props = valid_props();
811	        props["parameters"][0]["value"] = json!(99.0);
812	        props["plot"]["x"]["samples"] = json!(50_000);
813	        let config = PlotConfig::parse(&props).unwrap();
814	        assert_eq!(config.parameters[0].value, 3.0);
815	        assert_eq!(config.x.samples, MAX_SAMPLES);
816	    }
817	
818	    #[test]
819	    fn config_rejects_malformed_excessive_and_noncanonical_props() {
820	        assert!(PlotConfig::parse(&json!({})).is_err());
821	        let mut props = valid_props();
822	        props["parameters"] = Value::Array(
823	            (0..=MAX_PARAMETERS)
824	                .map(|index| {
825	                    json!({
826	                        "id": format!("p{index}"), "min": 0, "max": 1
827	                    })
828	                })
829	                .collect(),
830	        );
831	        assert!(PlotConfig::parse(&props).is_err());
832	
833	        let mut props = valid_props();
834	        props["parameters"][0]["id"] = json!("DecayRate");
835	        assert!(PlotConfig::parse(&props).is_err());
836	    }
837	
838	    #[test]
839	    fn config_rejects_extreme_finite_ranges_with_overflowing_spans() {
840	        let mut props = valid_props();
841	        props["parameters"][0]["min"] = json!(-1e308);
842	        props["parameters"][0]["max"] = json!(1e308);
843	        assert!(PlotConfig::parse(&props)
844	            .unwrap_err()
845	            .contains("finite positive span"));
846	
847	        let mut props = valid_props();
848	        props["plot"]["x"]["min"] = json!(-1e308);
849	        props["plot"]["x"]["max"] = json!(1e308);
850	        assert!(PlotConfig::parse(&props)
851	            .unwrap_err()
852	            .contains("finite positive span"));
853	    }
854	
855	    #[test]
856	    fn config_preserves_ordinary_finite_ranges_and_default_step() {
857	        let config = PlotConfig::parse(&valid_props()).unwrap();
858	        assert_eq!((config.x.min, config.x.max), (0.0, 10.0));
859	        assert_eq!(
860	            (config.parameters[0].min, config.parameters[0].max),
861	            (0.1, 3.0)
862	        );
863	        assert!((config.parameters[0].step - 0.029).abs() < f64::EPSILON);
864	    }
865	
866	    #[test]
867	    fn format_value_preserves_integer_zeroes_at_zero_precision() {
868	        assert_eq!(format_value(0.0, 0), "0");
869	        assert_eq!(format_value(10.0, 0), "10");
870	        assert_eq!(format_value(100.0, 0), "100");
871	        assert_eq!(format_value(10.50, 2), "10.5");
872	    }
873	
874	    #[test]
875	    fn sampled_plot_is_finite_and_stays_inside_viewbox() {
876	        let config = PlotConfig::parse(&valid_props()).unwrap();
877	        let parameters = BTreeMap::from([("rate".into(), 1.0)]);
878	        let plot = sample_plot(&config, &parameters).unwrap();
879	        assert_eq!(plot.paths.len(), 1);
880	        assert!(plot.y_min.is_finite() && plot.y_max.is_finite());
881	        for pair in plot.paths[0].split_whitespace() {
882	            let (_, coordinates) = pair.split_at(1);
883	            let (x, y) = coordinates.split_once(',').unwrap();
884	            assert!((0.0..=120.0).contains(&x.parse::<f64>().unwrap()));
885	            assert!((0.0..=60.0).contains(&y.parse::<f64>().unwrap()));
886	        }
887	    }
888	
889	    #[test]
890	    fn sampled_plot_rejects_extreme_ranges_that_overflow_normalization() {
891	        let mut props = valid_props();
892	        props["plot"]["x"]["min"] = json!(-1.0);
893	        props["plot"]["x"]["max"] = json!(1.0);
894	        props["plot"]["series"] = json!([
895	            {"label":"Extreme", "expression":"x*1e308"}
896	        ]);
897	        let config = PlotConfig::parse(&props).unwrap();
898	        let parameters = BTreeMap::from([("rate".into(), 1.0)]);
899	        let error = sample_plot(&config, &parameters).unwrap_err();
900	        assert!(error.contains("too large") || error.contains("invalid normalized"));
901	    }
902	}

