479	#[derive(Debug, PartialEq)]
480	struct SampledPlot {
481	    paths: Vec<String>,
482	    y_min: f64,
483	    y_max: f64,
484	}
485	
486	fn sample_plot(
487	    config: &PlotConfig,
488	    parameters: &BTreeMap<String, f64>,
489	) -> Result<SampledPlot, String> {
490	    let mut values = parameters.clone();
491	    let mut sampled = vec![Vec::with_capacity(config.x.samples); config.series.len()];
492	    let mut y_min = f64::INFINITY;
493	    let mut y_max = f64::NEG_INFINITY;
494	
495	    for sample in 0..config.x.samples {
496	        let progress = sample as f64 / (config.x.samples - 1) as f64;
497	        let x = config.x.min + progress * (config.x.max - config.x.min);
498	        values.insert(config.x.id.clone(), x);
499	        for (index, series) in config.series.iter().enumerate() {
500	            let y = series
501	                .expression
502	                .evaluate(&values)
503	                .map_err(|error| format!("{} could not be evaluated: {error}", series.label))?;
504	            y_min = y_min.min(y);
505	            y_max = y_max.max(y);
506	            sampled[index].push((progress, y));
507	        }
508	    }
509	
510	    if !y_min.is_finite() || !y_max.is_finite() {
511	        return Err("the plot did not produce finite values".into());
512	    }
513	    if (y_max - y_min).abs() < f64::EPSILON {
514	        let padding = y_max.abs().max(1.0) * 0.05;
515	        let padded_min = y_min - padding;
516	        let padded_max = y_max + padding;
517	        if !padded_min.is_finite() || !padded_max.is_finite() {
518	            return Err("the plot range is too large to normalize".into());
519	        }
520	        y_min = padded_min;
521	        y_max = padded_max;
522	    }
523	    let span = y_max - y_min;
524	    if !span.is_finite() || span <= 0.0 {
525	        return Err("the plot range is too large to normalize".into());
526	    }
527	    let paths = sampled
528	        .into_iter()
529	        .map(|points| {
530	            points
531	                .into_iter()
532	                .enumerate()
533	                .map(|(index, (x, y))| {
534	                    let command = if index == 0 { 'M' } else { 'L' };
535	                    let plot_x = x * 120.0;
536	                    let plot_y = 60.0 - (y - y_min) / span * 60.0;
537	                    if !plot_x.is_finite() || !plot_y.is_finite() {
538	                        return Err("the plot produced invalid normalized geometry".to_string());
539	                    }
540	                    Ok(format!("{command}{plot_x:.3},{plot_y:.3}"))
541	                })
542	                .collect::<Result<Vec<_>, _>>()
543	                .map(|segments| segments.join(" "))
544	        })
545	        .collect::<Result<Vec<_>, _>>()?;
546	    Ok(SampledPlot {
547	        paths,
548	        y_min,
549	        y_max,
550	    })
551	}
552	
553	fn update_parameter(
554	    values: RwSignal<BTreeMap<String, f64>>,
555	    parameter: &Parameter,
556	    raw: &str,
557	) -> Option<f64> {
558	    let value = raw.parse::<f64>().ok()?;
559	    if !value.is_finite() {
560	        return None;
561	    }
562	    let value = value.clamp(parameter.min, parameter.max);
563	    values.update(|current| {
564	        current.insert(parameter.id.clone(), value);
565	    });
566	    Some(value)
567	}
568	
569	fn format_value(value: f64, precision: usize) -> String {
570	    let rendered = format!("{value:.precision$}");
571	    let Some((whole, fraction)) = rendered.split_once('.') else {
572	        return rendered;
573	    };
574	    let fraction = fraction.trim_end_matches('0');
575	    if fraction.is_empty() {
576	        whole.to_string()
577	    } else {
578	        format!("{whole}.{fraction}")
579	    }
580	}
