3267	    async fn hydrate_active_session(&self, id: &str) -> Result<Vec<String>, String> {
3268	        let url = self.url.get_untracked();
3269	        let get_url = format!("{}/v1/sessions/{id}", url.trim_end_matches('/'));
3270	        let resp = Request::get(&get_url)
