4300	fn close_planner_stream_sources(sources: &Rc<RefCell<PlannerStreamSources>>) {
4301	    let (agent, permission) = {
4302	        let mut sources = sources.borrow_mut();
4303	        let agent = sources.agent.take();
4304	        let permission = sources.permission.take();
4305	        sources.session_id.clear();
4306	        sources.generation = 0;
4307	        sources.lifecycle.reset();
4308	        (agent, permission)
4309	    };
4310	    // gloo-net 0.6 clones share one web_sys::EventSource. `close` wakes the
4311	    // subscriber stream; doing it after the borrow is released avoids a
4312	    // re-entrant RefCell borrow through the dispatched close notification.
4313	    if let Some(agent) = agent {
4314	        agent.close();
4315	    }
4316	    if let Some(permission) = permission {
4317	        permission.close();
4318	    }
4319	}
