4321	fn set_stream_source(
4322	    sources: &Rc<RefCell<PlannerStreamSources>>,
4323	    session_id: &str,
4324	    generation: u64,
4325	    permission: bool,
4326	    source: Option<EventSource>,
4327	) {
4328	    let previous = {
4329	        let mut sources = sources.borrow_mut();
4330	        if sources.session_id != session_id || sources.generation != generation {
4331	            return;
4332	        }
4333	        let state = source
4334	            .as_ref()
4335	            .map(EventSource::state)
4336	            .unwrap_or(EventSourceState::Closed);
4337	        let (kind, previous) = if permission {
4338	            (
4339	                PlannerStreamKind::Permission,
4340	                std::mem::replace(&mut sources.permission, source),
4341	            )
4342	        } else {
4343	            (
4344	                PlannerStreamKind::Agent,
4345	                std::mem::replace(&mut sources.agent, source),
4346	            )
4347	        };
4348	        sources.lifecycle.transition(kind, state);
4349	        previous
4350	    };
4351	    if let Some(previous) = previous {
4352	        previous.close();
4353	    }
4354	}
