4360	/// Mark one already-installed CONNECTING source OPEN without replacing its
4361	/// stored clone. Replacement would drop/close the exact source we just awaited.
4362	fn mark_stream_source_open(
4363	    sources: &Rc<RefCell<PlannerStreamSources>>,
4364	    session_id: &str,
4365	    generation: u64,
4366	    permission: bool,
4367	) -> bool {
4368	    let mut sources = sources.borrow_mut();
4369	    if !stream_owner_matches(&sources, session_id, generation) {
4370	        return false;
4371	    }
4372	    let installed = if permission {
4373	        sources.permission.is_some()
4374	    } else {
4375	        sources.agent.is_some()
4376	    };
4377	    if !installed {
4378	        return false;
4379	    }
4380	    sources.lifecycle.transition(
4381	        if permission {
4382	            PlannerStreamKind::Permission
4383	        } else {
4384	            PlannerStreamKind::Agent
4385	        },
4386	        EventSourceState::Open,
4387	    );
4388	    true
4389	}
