2209	    /// frames, scoped to `active_session_id` and the current SSE `generation`.
2210	    ///
2211	    /// `EventSource` delivers frames by their `event:` name, so we subscribe to
2212	    /// `permission_request` and `permission_decision` by name (the same per-name
2213	    /// pattern the agent stream uses). The control stream is NOT session-scoped
2214	    /// server-side, so we drop any frame whose envelope `session_id` isn't ours.
2215	    /// When gating is off the daemon never emits these, so this stream just sits
2216	    /// idle — no behavior change for the ungated path.
2217	    fn connect_permission_stream(&self, active_session_id: String, generation: u64) {
2218	        let url = self.url.get_untracked();
2219	        let sse_generation = self.sse_generation;
2220	        let permission_stream_ready = self.permission_stream_ready;
2221	        let permission_revision = self.permission_revision;
2222	        let planner_stream_sources = self.planner_stream_sources.clone();
2223	        let pending = self.pending_permissions;
2224	
2225	        spawn_local(async move {
2226	            loop {
2227	                if sse_generation.get_untracked() != generation {
2228	                    break;
2229	                }
2230	                clear_stream_marker(permission_stream_ready, &active_session_id, generation);
2231	                set_stream_source(
2232	                    &planner_stream_sources,
2233	                    &active_session_id,
2234	                    generation,
2235	                    true,
2236	                    None,
2237	                );
2238	                let events_url = format!("{}/v1/events", url.trim_end_matches('/'));
2239	                let mut es = match EventSource::new(&events_url) {
2240	                    Ok(es) => es,
2241	                    Err(_) => {
2242	                        gloo_timers::future::TimeoutFuture::new(2_000).await;
2243	                        continue;
2244	                    }
2245	                };
2246	                let mut subs = Vec::new();
2247	                let mut sub_err = false;
2248	                for name in ["permission_request", "permission_decision"] {
2249	                    match es.subscribe(name) {
2250	                        Ok(s) => subs.push(s),
2251	                        Err(_) => {
2252	                            sub_err = true;
2253	                            break;
2254	                        }
2255	                    }
2256	                }
2257	                if sub_err {
2258	                    gloo_timers::future::TimeoutFuture::new(2_000).await;
2259	                    continue;
2260	                }
2261	
2262	                // Install while CONNECTING so a replacement generation owns
2263	                // and can close the permission source before OPEN resolves.
2264	                set_stream_source(
2265	                    &planner_stream_sources,
2266	                    &active_session_id,
2267	                    generation,
2268	                    true,
2269	                    Some(es.clone()),
2270	                );
2271	                let opened = await_event_source_open(&es).await;
2272	                if sse_generation.get_untracked() != generation
2273	                    || !stream_owner_matches(
2274	                        &planner_stream_sources.borrow(),
2275	                        &active_session_id,
2276	                        generation,
2277	                    )
2278	                {
2279	                    break;
2280	                }
2281	                if !opened {
2282	                    set_stream_source(
2283	                        &planner_stream_sources,
2284	                        &active_session_id,
2285	                        generation,
2286	                        true,
2287	                        None,
2288	                    );
2289	                    continue;
2290	                }
2291	                if !mark_stream_source_open(
2292	                    &planner_stream_sources,
2293	                    &active_session_id,
2294	                    generation,
2295	                    true,
2296	                ) {
2297	                    break;
2298	                }
2299	                permission_stream_ready.set(stream_marker_for_state(
2300	                    es.state(),
2301	                    &active_session_id,
2302	                    generation,
2303	                ));
2304	                spawn_local(monitor_stream_open(
2305	                    planner_stream_sources.clone(),
2306	                    permission_stream_ready,
2307	                    active_session_id.clone(),
2308	                    generation,
2309	                    true,
2310	                ));
2311	                let mut stream = futures_util::stream::select_all(subs);
2312	                while let Some(msg) = stream.next().await {
2313	                    if sse_generation.get_untracked() != generation {
2314	                        break;
2315	                    }
2316	                    let Ok((_event_name, msg)) = msg else {
2317	                        break;
2318	                    };
2319	                    let Some(data) = msg.data().as_string() else {
2320	                        continue;
2321	                    };
2322	                    let Ok(evt) = serde_json::from_str::<ControlEvent>(&data) else {
2323	                        continue;
2324	                    };
2325	                    permission_revision.update(|revision| *revision = revision.wrapping_add(1));
2326	                    apply_control_event(&evt, &active_session_id, pending);
2327	                }
2328	
2329	                clear_stream_marker(permission_stream_ready, &active_session_id, generation);
2330	                set_stream_source(
2331	                    &planner_stream_sources,
2332	                    &active_session_id,
2333	                    generation,
2334	                    true,
2335	                    None,
2336	                );
2337	                if sse_generation.get_untracked() != generation {
2338	                    break;
2339	                }
2340	                gloo_timers::future::TimeoutFuture::new(1_000).await;
2341	            }
2342	        });
2343	    }
2344	
2345	    /// Record an allow/deny decision for a pending permission by POSTing
2346	    /// `/v1/permissions/{id}/decision`. The body matches the daemon's
2347	    /// `PermissionDecisionRequest`: `{ "permission_id": <id>, "decision":
2348	    /// "allow" }` or `{ "permission_id": <id>, "decision": "deny" }` (the
2349	    /// `decision` enum is `#[serde(tag = "decision")]`, flattened into the
2350	    /// request). Includes `decision_token` (OCEAN-185 / OCEAN-314) — the same
4400	        let state = {
4401	            let sources = sources.borrow();
4402	            if sources.session_id != session_id || sources.generation != generation {
4403	                return;
4404	            }
4405	            let source = if permission {
4406	                sources.permission.as_ref()
4407	            } else {
4408	                sources.agent.as_ref()
4409	            };
4410	            source.map(EventSource::state)
4411	        };
4412	        if state == Some(EventSourceState::Open) {
4413	            continue;
4414	        }
4415	        clear_stream_marker(marker, &session_id, generation);
4416	        set_stream_source(&sources, &session_id, generation, permission, None);
4417	        return;
4418	    }
4419	}
4420	
4421	fn planner_sources_open(sources: &PlannerStreamSources, session_id: &str, generation: u64) -> bool {
4422	    sources.session_id == session_id
4423	        && sources.generation == generation
4424	        && sources.lifecycle.ready()
4425	        && sources
4426	            .agent
4427	            .as_ref()
4428	            .is_some_and(|source| source.state() == EventSourceState::Open)
4429	        && sources
4430	            .permission
4431	            .as_ref()
4432	            .is_some_and(|source| source.state() == EventSourceState::Open)
4433	}
4434	
4435	fn clear_stream_marker(marker: RwSignal<Option<(String, u64)>>, session_id: &str, generation: u64) {
4436	    if marker.with_untracked(|value| {
4437	        value
4438	            .as_ref()
4439	            .is_some_and(|(id, current)| id == session_id && *current == generation)
4440	    }) {
4441	        marker.set(None);
4442	    }
4443	}
4444	
4445	trait PermissionSnapshotSource {
4446	    fn revision(&self) -> u64;
4447	    fn fetch<'a>(&'a mut self) -> LocalBoxFuture<'a, Result<Vec<PendingPermission>, String>>;
4448	    fn apply(&mut self, snapshot: Vec<PendingPermission>);
4449	}
4450	
4451	async fn reconcile_permission_snapshot<S: PermissionSnapshotSource>(
4452	    source: &mut S,
4453	) -> Result<(), String> {
4454	    for _ in 0..4 {
4455	        let revision = source.revision();
4456	        let snapshot = source.fetch().await?;
4457	        if source.revision() != revision {
4458	            continue;
4459	        }
4460	        source.apply(snapshot);
4461	        return Ok(());
4462	    }
4463	    Err("permission snapshot changed repeatedly during reconciliation".into())
4464	}
4465	
4466	struct DaemonPermissionSnapshotSource<'a> {
4467	    daemon: &'a Daemon,
4468	    session_id: &'a str,
4469	}
4470	
4471	impl PermissionSnapshotSource for DaemonPermissionSnapshotSource<'_> {
4472	    fn revision(&self) -> u64 {
4473	        self.daemon.permission_revision.get_untracked()
4474	    }
