 250	/// Race safety: both the `event.listen` IPC (registering the subscriber) and
 251	/// this command travel the webview's single FIFO IPC channel, and `listen` is
 252	/// dispatched first (see app.rs), so the subscriber is registered before the
 253	/// drain emits — no replayed event is lost.
 254	#[tauri::command]
 255	fn ui_ready(app: AppHandle, state: State<'_, AppState>) -> Result<(), String> {
 256	    let pending = {
 257	        let mut bridge = state.menu.lock();
 258	        bridge.ready = true;
 259	        std::mem::take(&mut bridge.pending)
 260	    };
 261	    for id in pending {
 262	        let _ = app.emit("menu-command", id);
 263	    }
 264	    Ok(())
 265	}
