1301	            // stays the always-available fallback.
1302	            let summon = Shortcut::new(Some(Modifiers::SUPER | Modifiers::SHIFT), Code::Space);
1303	            if let Err(e) = app.global_shortcut().register(summon) {
1304	                eprintln!("[ocean-tauri] could not register Cmd+Shift+Space global shortcut: {e}");
1305	            }
1306	            Ok(())
1307	        })
1308	        .on_window_event(|window, event| {
1309	            // Menubar-app pattern: closing the main window hides it to the tray
1310	            // rather than quitting. Real quit is via tray "Quit" (or Cmd+Q).
1311	            if window.label() != "main" {
1312	                return;
1313	            }
1314	            if let WindowEvent::CloseRequested { api, .. } = event {
1315	                api.prevent_close();
1316	                let _ = window.hide();
1317	            }
1318	        })
1319	        .on_menu_event(|app, event| {
1320	            // Re-emit app-menu selections as `menu-command`, carrying the menu
1321	            // item's id. The wasm host bridge (host::on_menu_command) routes
1322	            // the id to CommandRegistry::run; unknown ids — and the predefined
1323	            // About/Quit roles, which also act natively — resolve to a no-op
1324	            // inside the registry lookup, so emitting them is harmless. (Tray-
1325	            // menu selections are handled by the tray's own on_menu_event and
1326	            // never reach here.)
1327	            //
1328	            // Readiness gate: until the wasm `menu-command` listener attaches,
1329	            // Tauri drops events with no subscriber. Selections arriving
1330	            // pre-attach are queued in `MenuBridge::pending` and replayed (in
1331	            // arrival order) by `ui_ready` once the bundle signals readiness.
1332	            // After that, emit immediately.
1333	            let id = event.id.as_ref().to_string();
1334	            let state = app.state::<AppState>();
1335	            let mut guard = state.menu.lock();
1336	            if guard.ready {
1337	                drop(guard);
1338	                let _ = app.emit("menu-command", &id);
1339	            } else {
1340	                guard.pending.push(id);
1341	            }
1342	        })
1343	        .invoke_handler(tauri::generate_handler![
1344	            pick_folder,
1345	            watch_paths,
1346	            unwatch_paths,
1347	            repo_state,
1348	            set_badge,
1349	            daemon_status,
1350	            daemon_start,
1351	            daemon_stop,
1352	            daemon_restart,
1353	            ui_ready,
1354	            ui_debug_resize
1355	        ])
1356	        .run(tauri::generate_context!())
1357	        .expect("error while running ocean-tauri");
1358	}

