   1	/* Dynamic Island — native agent interaction, Sessions, and Recall. Tauri-only
   2	   in the component tree; these selectors remain inert on web/extension hosts. */
   3	
   4	:root {
   5	  --island-compact-w: 380px;
   6	  --island-top: 64px;
   7	}
   8	
   9	/* Center inside the real header/content column without transform. Fixed
  10	   descendants therefore stay viewport-fixed instead of inheriting a new
  11	   containing block. The percentage cap reserves both titlebar control zones. */
  12	.island-host {
  13	  position: absolute;
  14	  inset-inline: 0;
  15	  top: 11px;
  16	  width: min(var(--island-compact-w), 44%);
  17	  height: var(--ctl-h);
  18	  margin-inline: auto;
  19	  z-index: 122;
  20	}
  21	
  22	.island-chip {
  23	  box-sizing: border-box;
  24	  position: relative;
  25	  z-index: 122;
  26	  display: flex;
  27	  align-items: center;
  28	  gap: 7px;
  29	  width: 100%;
  30	  max-width: 100%;
  31	  height: var(--ctl-h);
  32	  min-width: 0;
  33	  padding: 0 12px;
  34	  border: 0;
  35	  border-radius: var(--radius);
  36	  background: var(--bg-elevated);
  37	  box-shadow: var(--elev-1);
  38	  color: var(--fg);
  39	  font: 500 12px/1 var(--font);
  40	  cursor: pointer;
  41	  overflow: hidden;
  42	  transition: background var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease);
  43	}
  44	
  45	.island-chip:hover {
  46	  background: var(--bg-hover);
  47	}
  48	
  49	/* Once expanded, the compact control becomes the stage's top rail instead of
  50	   remaining a raised pill on top of a second surface. Keeping its hit target
  51	   and text while dissolving its own fill/elevation makes the Island read as
  52	   one object changing shape. */
  53	.island-chip[aria-expanded="true"],
  54	.island-chip[aria-expanded="true"]:hover {
  55	  background: transparent;
  56	  box-shadow: none;
  57	}
  58	
  59	.island-chip:focus-visible {
  60	  box-shadow: var(--elev-1), var(--focus-ring);
  61	}
  62	
  63	.island-chip__dot {
  64	  width: 7px;
  65	  height: 7px;
  66	  flex: 0 0 7px;
  67	  border-radius: var(--radius-pill);
  68	  background: var(--fg-3);
  69	}
  70	
  71	.island-chip__dot.is-empty {
  72	  background: var(--fg-4);
  73	}
  74	
  75	.island-chip.is-attention .island-chip__count {
  76	  color: var(--warn);
  77	}
  78	
  79	.island-chip__dot.is-attention {
  80	  background: var(--warn);
  81	}
  82	
  83	.island-chip.is-running .island-chip__count {
  84	  color: var(--accent);
  85	}
  86	
  87	.island-chip__dot.is-running {
  88	  background: var(--accent);
  89	}
  90	
  91	.island-live {
  92	  position: absolute;
  93	  width: 1px;
  94	  height: 1px;
  95	  padding: 0;
  96	  margin: -1px;
  97	  overflow: hidden;
  98	  clip: rect(0, 0, 0, 0);
  99	  white-space: nowrap;
 100	}
 101	
 102	.island-chip__title,
 103	.island-chip__project,
 104	.island-chip__count {
 105	  min-width: 0;
 106	  overflow: hidden;
 107	  text-overflow: ellipsis;
 108	  white-space: nowrap;
 109	}
 110	
 111	.island-chip__title {
 112	  flex: 1 1 auto;
 113	  text-align: left;
 114	}
 115	
 116	.island-chip__project {
 117	  flex: 0 1 auto;
 118	  color: var(--fg-2);
 119	}
 120	
 121	.island-chip__count,
 122	.island-chip__separator {
 123	  flex: 0 0 auto;
 124	  color: var(--fg-2);
 125	}
