 230	  overflow: hidden;
 231	}
 232	
 233	.island-result__meta > span {
 234	  min-width: 0;
 235	  max-width: 18ch;
 236	  overflow: hidden;
 237	  text-overflow: ellipsis;
 238	}
 239	
 240	.island-result__meta > span:empty {
 241	  display: none;
 242	}
 243	
 244	.island-result__meta > span:not(:empty) ~ span:not(:empty)::before {
 245	  content: "·";
