 252	}
 253	
 254	.island-empty {
 255	  padding: 28px 16px;
 256	  color: var(--fg-3);
 257	  font: 400 12px/1.4 var(--font);
 258	  text-align: center;
 259	}
 260	
 261	@media (max-width: 1000px) {
 262	  .island-host {
 263	    width: min(300px, 42%);
 264	  }
 265	
 266	  .island-chip__project,
 267	  .island-chip__separator {
 268	    display: none;
 269	  }
 270	}
 271	
 272	/* Below the split-view breakpoint the workspace overlays from the right.
 273	   Center the chip in the still-visible transcript column so workspace tabs
 274	   never paint through the titlebar control. The popover remains viewport-wide
 275	   and above the workspace, preserving the compact overlay behavior. */
 276	@media (max-width: 899px) {
 277	  .has-workspace-open .island-host {
 278	    right: var(--workspace-w);
 279	    /* The workspace resizer may intentionally leave only a 48px context
 280	       sliver. Collapse rather than painting through traffic lights or tabs
 281	       when that sliver cannot safely hold the interactive titlebar control. */
 282	    max-width: max(0px, calc(100vw - var(--workspace-w) - 160px));
 283	  }
 284	}
 285	
 286	@media (min-width: 721px) and (max-width: 840px) {
 287	  .has-workspace-open .island-host {
 288	    max-width: max(0px, calc(100vw - var(--workspace-w) - 220px));
 289	  }
 290	}
 291	
 292	@media (min-width: 841px) and (max-width: 899px) {
 293	  .has-workspace-open .island-host {
 294	    max-width: max(0px, calc(100vw - var(--workspace-w) - 300px));
 295	  }
 296	}
 297	
 298	@media (max-width: 840px) {
 299	  .island-host {
 300	    width: min(240px, 38%);
 301	  }
 302	
 303	  .island-chip {
 304	    padding-inline: 9px;
 305	  }
 306	
 307	}
 308	
 309	@media (max-width: 720px) {
