 315	/* Dynamic Island v2 — one titlebar object, three mutually exclusive tools.
 316	   The fixed outer stage begins behind the compact capsule so opening reads as
 317	   the object changing shape, not a button spawning a detached modal. */
 318	.island-dismiss-layer {
 319	  position: fixed;
 320	  inset: 0;
 321	  z-index: 120;
 322	  background: transparent;
 323	}
 324	
 325	.island-stage {
 326	  --island-stage-radius: 22px;
 327	  --island-stage-pad: 6px;
 328	  position: fixed;
 329	  top: 8px;
 330	  left: 16px;
 331	  right: 16px;
 332	  z-index: 121;
 333	  box-sizing: border-box;
 334	  width: min(520px, calc(100vw - 32px));
 335	  max-height: min(520px, calc(100vh - 24px));
 336	  margin-inline: auto;
 337	  padding: 48px var(--island-stage-pad) var(--island-stage-pad);
 338	  border: 1px solid var(--border-subtle);
 339	  border-radius: var(--island-stage-radius);
 340	  outline: none;
 341	  background: var(--sheen), var(--bg-raised);
