  3536	    /// Send a component interaction event back to the daemon.
  3537	    /// This is how the web surface tells the agent "user clicked a kanban card"
  3538	    /// or "user submitted a form". If a `component_wait` is pending on the
  3539	    /// agent side, it resolves immediately; otherwise the event is queued for
  3540	    /// the next turn.
  3541	    pub fn send_component_event(&self, component_id: String, payload: Value) {
  3542	        let sid = self.session_id.get_untracked();
  3543	        let Some(session_id) = sid else {
  3544	            self.status.set("no session — send a prompt first".into());
  3545	            return;
  3546	        };
  3547	        let url = self.url.get_untracked();
  3548	        let status = self.status;
  3549	        spawn_local(async move {
  3550	            let body = ComponentEventRequest {
  3551	                session_id,
  3552	                component_id,
  3553	                event: payload,
  3554	            };
  3555	            let post_url = format!("{}/v1/component/event", url.trim_end_matches('/'));
  3556	            let res = Request::post(&post_url)
  3557	                .header("content-type", "application/json")
  3558	                .json(&body);
  3559	            let res = match res {
  3560	                Ok(req) => req.send().await,
  3561	                Err(err) => {
  3562	                    let raw = err.to_string();
  3563	                    log::error!("component event encode error: {raw}");
  3564	                    status.set(format!(
  3565	                        "component event encode error: {}",
  3566	                        concise_error(&raw)
  3567	                    ));
  3568	                    return;
  3569	                }
  3570	            };
  3571	            match res {
  3572	                Ok(resp) => {
  3573	                    if !resp.ok() {
  3574	                        let text = resp.text().await.unwrap_or_default();
  3575	                        // A wait-miss is a benign race, not an operator-facing
  3576	                        // fault: the agent's `component_wait` already resolved
  3577	                        // (or was never armed) when the click landed — the
  3578	                        // daemon answers 404 "no pending wait for component" /
  3579	                        // 410 "nobody waiting". Surfacing that as a status
  3580	                        // toast made every stray click look like a failure.
  3581	                        if text.contains("no pending wait") || text.contains("nobody waiting") {
  3582	                            log::warn!("component event ignored (no waiter): {text}");
  3583	                        } else {
  3584	                            log::error!("component event error: {text}");
  3585	                            status.set(format!("component event error: {}", concise_error(&text)));
  3586	                        }
  3587	                    }
  3588	                }
  3589	                Err(err) => {
  3590	                    let raw = err.to_string();
  3591	                    log::error!("component event post error: {raw}");
  3592	                    status.set(format!(
  3593	                        "component event post error: {}",
  3594	                        concise_error(&raw)
  3595	                    ));
  3596	                }
  3597	            }
  3598	        });
  3599	    }
