  1	use std::sync::{Arc, LazyLock};
  2	
  3	use axum::{
  4	    extract::{Query, State},
  5	    http::StatusCode,
  6	    Json,
  7	};
  8	use ocean_agent::{
  9	    AgentRuntime, HistorySearchCapacityError, HistorySearchHit, MAX_HISTORY_SEARCH_QUERY_CHARS,
 10	    MAX_HISTORY_SEARCH_STORE_BYTES,
 11	};
 12	use serde::{Deserialize, Serialize};
 13	use tokio::sync::Semaphore;
 14	
 15	use super::AppState;
 16	
 17	/// A typeahead client can supersede a request before its blocking filesystem
 18	/// scan notices. Bound concurrent scans globally so abandoned/parallel queries
 19	/// cannot flood Tokio's blocking pool or multiply full-store I/O without limit.
 20	const MAX_CONCURRENT_HISTORY_SEARCHES: usize = 2;
 21	static HISTORY_SEARCH_SLOTS: LazyLock<Arc<Semaphore>> =
 22	    LazyLock::new(|| Arc::new(Semaphore::new(MAX_CONCURRENT_HISTORY_SEARCHES)));
 23	
 24	#[derive(Debug, Default, Deserialize)]
 25	pub(super) struct HistorySearchQuery {
 26	    #[serde(default)]
 27	    q: Option<String>,
 28	    #[serde(default)]
 29	    limit: Option<usize>,
 30	}
 31	
 32	#[derive(Debug, Serialize)]
 33	pub(super) struct HistorySearchResponse {
 34	    ok: bool,
 35	    query: String,
 36	    hits: Vec<HistorySearchHit>,
 37	    error: Option<String>,
 38	}
 39	
 40	/// `GET /v1/agent/history/search` searches only ocean-agent's persisted,
 41	/// display-ready transcript projection. The blocking file scan runs off the
 42	/// async executor and cannot invoke a provider or embedding service.
 43	pub(super) async fn history_search(
 44	    State(state): State<AppState>,
 45	    Query(params): Query<HistorySearchQuery>,
 46	) -> (StatusCode, Json<HistorySearchResponse>) {
 47	    let query = params.q.unwrap_or_default();
 48	    if query.trim().is_empty() {
 49	        return response(
 50	            StatusCode::BAD_REQUEST,
 51	            query,
 52	            Vec::new(),
 53	            Some("query parameter q must not be empty".into()),
 54	        );
 55	    }
 56	    if query.trim().chars().count() > MAX_HISTORY_SEARCH_QUERY_CHARS {
 57	        return response(
 58	            StatusCode::BAD_REQUEST,
 59	            query,
 60	            Vec::new(),
 61	            Some(format!(
 62	                "query exceeds {MAX_HISTORY_SEARCH_QUERY_CHARS} characters"
 63	            )),
 64	        );
 65	    }
 66	    let permit = match HISTORY_SEARCH_SLOTS.clone().try_acquire_owned() {
 67	        Ok(permit) => permit,
 68	        Err(_) => {
 69	            return response(
 70	                StatusCode::TOO_MANY_REQUESTS,
 71	                query,
 72	                Vec::new(),
 73	                Some("too many transcript history searches are already running".into()),
 74	            );
 75	        }
 76	    };
 77	
 78	    let runtime: Arc<AgentRuntime> = state.runtime.clone();
 79	    let search_query = query.clone();
 80	    match tokio::task::spawn_blocking(move || {
 81	        let _permit = permit;
 82	        runtime.search_history(&search_query, params.limit)
 83	    })
 84	    .await
 85	    {
 86	        Ok(Ok(hits)) => response(StatusCode::OK, query, hits, None),
 87	        Ok(Err(error)) => {
 88	            tracing::warn!(error = %error, "history transcript search failed");
 89	            search_error_response(query, &error)
 90	        }
 91	        Err(error) => {
 92	            tracing::warn!(error = %error, "history transcript search task failed");
 93	            response(
 94	                StatusCode::INTERNAL_SERVER_ERROR,
 95	                query,
 96	                Vec::new(),
 97	                Some("transcript history could not be searched".into()),
 98	            )
 99	        }
100	    }
101	}
102	
103	fn search_error_response(
104	    query: String,
105	    error: &anyhow::Error,
106	) -> (StatusCode, Json<HistorySearchResponse>) {
107	    if error.downcast_ref::<HistorySearchCapacityError>().is_some() {
108	        response(
109	            StatusCode::SERVICE_UNAVAILABLE,
110	            query,
111	            Vec::new(),
112	            Some(format!(
113	                "transcript history exceeds the {} MiB search capacity",
114	                MAX_HISTORY_SEARCH_STORE_BYTES / (1024 * 1024)
115	            )),
116	        )
117	    } else {
118	        response(
119	            StatusCode::INTERNAL_SERVER_ERROR,
120	            query,
121	            Vec::new(),
122	            Some("transcript history could not be searched".into()),
123	        )
124	    }
125	}
126	
127	fn response(
128	    status: StatusCode,
129	    query: String,
130	    hits: Vec<HistorySearchHit>,
131	    error: Option<String>,
132	) -> (StatusCode, Json<HistorySearchResponse>) {
133	    (
134	        status,
135	        Json(HistorySearchResponse {
136	            ok: status.is_success(),
137	            query,
138	            hits,
139	            error,
140	        }),
141	    )
142	}
143	
144	#[cfg(test)]
145	mod tests {
146	    use super::*;
147	
148	    #[test]
149	    fn capacity_errors_map_to_an_explicit_service_response() {
150	        let error: anyhow::Error = HistorySearchCapacityError {
151	            observed_bytes: MAX_HISTORY_SEARCH_STORE_BYTES + 1,
152	            max_bytes: MAX_HISTORY_SEARCH_STORE_BYTES,
153	        }
154	        .into();
155	        let (status, Json(body)) = search_error_response("ocean".into(), &error);
156	        assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE);
157	        assert!(!body.ok);
158	        assert_eq!(body.query, "ocean");
159	        assert!(body.hits.is_empty());
160	        assert!(body
161	            .error
162	            .as_deref()
163	            .unwrap()
164	            .contains("64 MiB search capacity"));
165	    }
166	}
 98	/// Classification of a deterministic transcript-text match.
 99	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
100	#[serde(rename_all = "lowercase")]
101	pub enum HistoryMatchKind {
102	    Exact,
103	    Lexical,
104	    Fuzzy,
105	}
106	
107	/// One display-transcript match returned by daemon-owned history search.
108	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
109	pub struct HistorySearchHit {
110	    pub hit_id: String,
111	    pub session_id: SessionId,
112	    pub session_title: String,
113	    pub role: String,
114	    pub excerpt: String,
115	    #[serde(default, skip_serializing_if = "Option::is_none")]
116	    pub timestamp_ms: Option<i64>,
117	    /// Always serialized (`null` for unbound legacy sessions) so Recall clients
118	    /// receive one stable hit shape.
119	    #[serde(default)]
120	    pub workspace_root: Option<String>,
121	    pub score: f64,
122	    pub match_kind: HistoryMatchKind,
123	}
124	
125	/// Clamp a caller-supplied collection-list limit into the allowed range. `None`
126	/// ⇒ [`DEFAULT_LIST_LIMIT`]; any value is capped at [`MAX_LIST_LIMIT`] and
127	/// floored at 1 so `0` can never request an empty-yet-`has_more` page.
128	pub fn clamp_list_limit(limit: Option<usize>) -> usize {
129	    limit.unwrap_or(DEFAULT_LIST_LIMIT).clamp(1, MAX_LIST_LIMIT)
130	}

