125	/// Clamp a caller-supplied collection-list limit into the allowed range. `None`
126	/// ⇒ [`DEFAULT_LIST_LIMIT`]; any value is capped at [`MAX_LIST_LIMIT`] and
127	/// floored at 1 so `0` can never request an empty-yet-`has_more` page.
128	pub fn clamp_list_limit(limit: Option<usize>) -> usize {
129	    limit.unwrap_or(DEFAULT_LIST_LIMIT).clamp(1, MAX_LIST_LIMIT)
130	}

